// Find the earliest Friday the 13th in the proleptic Gregorian calendar
// and count total Friday the 13ths in a 400-year cycle.

// Earliest Friday the 13th starting from 0001-01-01
DateOnly date = new(1, 1, 13);
while (date.DayOfWeek != DayOfWeek.Friday)
{
    date = date.AddMonths(1);
}
Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd}");

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
DateOnly start = new(1, 1, 13);
for (int i = 0; i < 400 * 12; i++)
{
    var d = start.AddMonths(i);
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
}
Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// Bonus: which day of the week is most likely to fall on the 13th?
var dayCounts = new int[7];
for (int i = 0; i < 400 * 12; i++)
{
    var d = start.AddMonths(i);
    dayCounts[(int)d.DayOfWeek]++;
}

Console.WriteLine("\n13th falls on each day of the week:");
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-10} {dayCounts[(int)dow]}");
EOF
